void UMissionComponent::AcceptMission(FName MissionID)
{
	for (FMissionData& Mission : AvailableMissions)
	{
		if (Mission.MissionID == MissionID)
		{
			ActiveMissions.Add(Mission);
			AvailableMissions.Remove(Mission);
			return;
		}
	}
}

