bool UMissionComponent::CompleteMission(FName MissionID)
{
	for (int32 i = 0; i < ActiveMissions.Num(); ++i)
	{
		if (ActiveMissions[i].MissionID == MissionID)
		{
			FMissionData CompletedMission = ActiveMissions[i];

			// Add reward credits to player inventory if we have a reference to the owner's economy system
			if (GetOwner())
			{
				UPlayerInventoryComponent* InventoryComp = GetOwner()->FindComponentByClass<UPlayerInventoryComponent>();
				if (InventoryComp)
				{
					float RewardCredits = CompletedMission.RewardCredits;
					float CurrentCredits = InventoryComp->GetCredits();
					InventoryComp->SetCredits(CurrentCredits + RewardCredits);
				}
			}

			// Mark as completed and remove from active
			CompletedMissions.Add(MissionID);
			ActiveMissions.RemoveAt(i);

			return true;
		}
	}
	return false;
}

void UMissionComponent::FailMission(FName MissionID, const FString& Reason)
{
	for (int32 i = 0; i < ActiveMissions.Num(); ++i)
	{
		if (ActiveMissions[i].MissionID == MissionID)
		{
			FailedMissions.Add(MissionID);
			ActiveMissions.RemoveAt(i);
			return;
		}
	}
}

TArray<FMissionData> UMissionComponent::CheckMissionBoard(FName StationID)
{
	TArray<FMissionData> Missions;
	// Return missions available at this station
	for (const FMissionData& Mission : AvailableMissions)
	{
		if (Mission.OriginStation == StationID || Mission.DestinationStation == StationID)
		{
			Missions.Add(Mission);
		}
	}
	return Missions;
}

TArray<FMissionData> UMissionComponent::GetActiveMissions() const
{
	return ActiveMissions;
}

bool UMissionComponent::IsMissionCompleted(FName MissionID) const
{
	for (const FName& CompletedID : CompletedMissions)
	{
		if (CompletedID == MissionID)
		{
			return true;
		}
	}
	return false;
}
